import os
import numpy as np
import pandas as pd
from library.config import (
    TRAIN_DATA_PATH,
    VAL_DATA_PATH,
    TEST_DATA_PATH,
    WORKING_DIR,
    MARGIN_COLS,
    SHAPE_COLS,
    TEXTURE_COLS,
    ALL_FEATURE_COLS,
    ID_COL,
    TARGET_COL,
    FLOAT_PRECISION,
)
from library.image_features import process_images


class LeafDataManager:
    """
    Manages data loading, merging with morphometrics, and generating specific
    feature views for the SM-FRIE strategy.
    """

    def __init__(self):
        # Define the columns generated by image_features.extract_morphometrics
        self.morph_cols = [
            "hu_1",
            "hu_2",
            "hu_3",
            "hu_4",
            "hu_5",
            "hu_6",
            "hu_7",
            "aspect_ratio",
            "solidity",
            "extent",
            "eccentricity",
        ]

    def load_data(self, load_cached_data=True):
        """
        Loads training, validation, and test data.
        Merges tabular features with extracted morphometric features.
        Returns dictionaries containing the different feature views (Global, Margin, Shape, Texture, Morph).

        Args:
            load_cached_data (bool): If True, attempts to load pre-processed .npz files from working dir.

        Returns:
            tuple: (data_train, data_val, data_test)
                   Each is a dictionary with keys: 'global', 'margin', 'shape', 'texture', 'morph', 'ids',
                   and 'y' (for train/val).
        """
        # Define cache paths
        os.makedirs(WORKING_DIR, exist_ok=True)
        train_cache_path = os.path.join(WORKING_DIR, "data_train.npz")
        val_cache_path = os.path.join(WORKING_DIR, "data_val.npz")
        test_cache_path = os.path.join(WORKING_DIR, "data_test.npz")

        # 1. Try loading from cache
        if (
            load_cached_data
            and os.path.exists(train_cache_path)
            and os.path.exists(val_cache_path)
            and os.path.exists(test_cache_path)
        ):
            print("Loading processed data views from cache...")
            return (
                self._load_npz(train_cache_path),
                self._load_npz(val_cache_path),
                self._load_npz(test_cache_path),
            )

        # 2. Load Metadata
        print("Loading metadata CSVs...")
        df_train = pd.read_csv(TRAIN_DATA_PATH)
        df_val = pd.read_csv(VAL_DATA_PATH)
        df_test = pd.read_csv(TEST_DATA_PATH)

        # 3. Extract Morphometrics (handles its own caching via library.image_features)
        print("Processing images for morphometrics...")
        morph_train = process_images(
            df_train, "train", load_cached_data=load_cached_data
        )
        morph_val = process_images(df_val, "val", load_cached_data=load_cached_data)
        morph_test = process_images(df_test, "test", load_cached_data=load_cached_data)

        # 4. Merge DataFrames
        print("Merging tabular and morphometric data...")
        df_train = df_train.merge(morph_train, on=ID_COL, how="left")
        df_val = df_val.merge(morph_val, on=ID_COL, how="left")
        df_test = df_test.merge(morph_test, on=ID_COL, how="left")

        # 5. Prepare Views
        print("Generating feature views...")
        data_train = self._create_views(df_train, is_test=False)
        data_val = self._create_views(df_val, is_test=False)
        data_test = self._create_views(df_test, is_test=True)

        # 6. Save to Cache
        print("Caching processed data...")
        np.savez(train_cache_path, **data_train)
        np.savez(val_cache_path, **data_val)
        np.savez(test_cache_path, **data_test)

        return data_train, data_val, data_test

    def _create_views(self, df, is_test=False):
        """
        Extracts specific feature subsets and casts to float64.
        """
        # Fill NaNs in morphometrics with 0 (safe default for shape descriptors)
        df[self.morph_cols] = df[self.morph_cols].fillna(0.0)

        # Extract views
        # Global: All provided tabular features (192 dims)
        X_global = df[ALL_FEATURE_COLS].values.astype(FLOAT_PRECISION)

        # Stratified Views
        X_margin = df[MARGIN_COLS].values.astype(FLOAT_PRECISION)
        X_shape = df[SHAPE_COLS].values.astype(FLOAT_PRECISION)
        X_texture = df[TEXTURE_COLS].values.astype(FLOAT_PRECISION)

        # Morphometric View
        X_morph = df[self.morph_cols].values.astype(FLOAT_PRECISION)

        # IDs
        ids = df[ID_COL].values

        data = {
            "global": X_global,
            "margin": X_margin,
            "shape": X_shape,
            "texture": X_texture,
            "morph": X_morph,
            "ids": ids,
        }

        if not is_test:
            # Keep targets as strings, encoding handled by model training
            data["y"] = df[TARGET_COL].values

        return data

    def _load_npz(self, path):
        """
        Helper to load npz file back into a dictionary.
        """
        with np.load(path, allow_pickle=True) as f:
            # Convert NpzFile object to a standard dict
            return {key: f[key] for key in f.files}
